import {
  CliParseFailure,
  formatCliParseFailure,
  formatHelp,
  getProgramName,
  parseCommandLine,
} from './cli.mjs';
import { Draft7Validator } from './draft7_validator.mjs';
import { parseJsonString } from './json_runtime.mjs';
import { writeUnhandledPythonStyleError } from './py_errors.mjs';

function renderPythonBoolean(value) {
  return value ? 'True' : 'False';
}

export function runTest8(
  argv = process.argv.slice(2),
  scriptPath = process.argv[1],
) {
  const programName = getProgramName(scriptPath);
  let parsedCommand;

  try {
    parsedCommand = parseCommandLine(argv);
  } catch (error) {
    if (error instanceof CliParseFailure) {
      process.stderr.write(formatCliParseFailure(programName, error.message));
      return 2;
    }

    throw error;
  }

  if (parsedCommand.kind === 'help') {
    process.stdout.write(formatHelp(programName));
    return 0;
  }

  try {
    const schema = parseJsonString(parsedCommand.values.a);
    const validator = new Draft7Validator(schema);
    const typeChecker = validator.TYPE_CHECKER;
    const result = typeChecker.isType(parsedCommand.values.b, parsedCommand.values.b);

    console.log(renderPythonBoolean(result));
    return 0;
  } catch (error) {
    writeUnhandledPythonStyleError(error);
    return 1;
  }
}

